#include <stdio.h>
#include <stdarg.h>
#include <string.h>

void join(char *out, const char *sep, ...) {
    va_list args;
    va_start(args, sep);
    out[0] = '\0';
    int first = 1;
    for (const char *w = va_arg(args, const char *); w != NULL; w = va_arg(args, const char *)) {
        if (!first) strcat(out, sep);
        strcat(out, w);
        first = 0;
    }
    va_end(args);
}

int main(void) {
    char sep[4], w1[16], w2[16], w3[16], buf[256];
    scanf("%3s %15s %15s %15s", sep, w1, w2, w3);
    join(buf, sep, w1, w2, w3, NULL);
    printf("[%s]\n", buf);
    join(buf, sep, w3, NULL);
    printf("[%s]\n", buf);
    join(buf, sep, NULL);
    printf("[%s]\n", buf);
    join(buf, sep, w2, w1, w2, w1, NULL);
    printf("[%s]\n", buf);
    return 0;
}
